
/* ==== INJECTED TEST CREDENTIALS (for local testing only) ==== */
/* The real app expects client credentials from platform-specific config.
   For development/testing we inject harmless dummy values so the app doesn't throw.
   NOTE: Playback and real auth may still fail without valid Spotify credentials.
*/
(function(){
  try {
    if (!window.__SPOTIFY_CLIENT_ID) {
      window.__SPOTIFY_CLIENT_ID = "1e7db9c88a474460b5f8b077db4b954d";
      console.info("[inject] set __SPOTIFY_CLIENT_ID (dummy)");
    }
    if (!window.__SPOTIFY_CLIENT_SECRET) {
      window.__SPOTIFY_CLIENT_SECRET = "a1f042f61d9b493d996113b4c33bcaf7";
      console.info("[inject] set __SPOTIFY_CLIENT_SECRET (dummy)");
    }
    // Some builds expect a config object named CLIENT_CREDENTIALS or similar
    if (!window.__SPOTIFY_CREDENTIALS) {
      window.__SPOTIFY_CREDENTIALS = {
        client_id: window.__SPOTIFY_CLIENT_ID,
        client_secret: window.__SPOTIFY_CLIENT_SECRET
      };
      console.info("[inject] created __SPOTIFY_CREDENTIALS object (dummy)");
    }
  } catch(e){ console.warn("[inject] failed to set dummy spotify creds", e); }
})();
