                    body: '#import "../../../libs/graphql/curiosity/fragments.gql"\n#import "../../../libs/graphql-tiles/fragments-tiles.gql"\n\nquery libraryAll(\n  $offset: Int = 0\n  $limit: Int = 50\n  $includePlaylists: Boolean = false\n  $includeAlbums: Boolean = false\n  $includePodcasts: Boolean = false\n  $includeArtists: Boolean = false\n  $includeAudiobooks: Boolean = false\n) {\n  me {\n    playlists: libraryV3(\n      pageInput: {\n        offset: $offset\n        limit: $limit\n        flatten: true\n        features: [LIKED_SONGS, YOUR_EPISODES_V2]\n        filterIds: ["Playlists"]\n        sortOrderId: "Custom Order"\n      }\n    ) @include(if: $includePlaylists) {\n      __typename\n      ... on LibraryPage {\n        totalCount\n        pagingInfo {\n          nextOffset\n        }\n        items {\n          item {\n            __typename\n            ... on LibraryPseudoPlaylistResponseWrapper {\n              data {\n                __typename\n                ... on PseudoPlaylist {\n                  name\n                  uri\n                  count\n                }\n              }\n            }\n            ...tilePlaylist\n          }\n        }\n      }\n    }\n    albums: libraryV3(pageInput: { offset: $offset, limit: $limit, flatten: true, filterIds: ["Albums"] })\n      @include(if: $includeAlbums) {\n      __typename\n      ... on LibraryPage {\n        totalCount\n        pagingInfo {\n          nextOffset\n        }\n        items {\n          item {\n            __typename\n            ...tileAlbum\n          }\n        }\n      }\n    }\n    artists: libraryV3(pageInput: { offset: $offset, limit: $limit, flatten: true, filterIds: ["Artists"] })\n      @include(if: $includeArtists) {\n      __typename\n      ... on LibraryPage {\n        totalCount\n        pagingInfo {\n          nextOffset\n        }\n        items {\n          item {\n            __typename\n            ...tileArtist\n          }\n        }\n      }\n    }\n    podcasts: libraryV3(pageInput: { offset: $offset, limit: $limit, flatten: true, filterIds: ["Podcasts & Shows"] })\n      @include(if: $includePodcasts) {\n      __typename\n      ... on LibraryPage {\n        totalCount\n        pagingInfo {\n          nextOffset\n        }\n        items {\n          item {\n            __typename\n            ...tilePodcast\n          }\n        }\n      }\n    }\n    audiobooks: libraryV3(pageInput: { offset: $offset, limit: $limit, flatten: true, filterIds: ["Audiobooks"] })\n      @include(if: $includeAudiobooks) {\n      __typename\n      ... on LibraryPage {\n        totalCount\n        pagingInfo {\n          nextOffset\n        }\n        items {\n          item {\n            __typename\n            ...tileAudiobook\n          }\n        }\n      }\n    }\n  }\n}\n\nquery libraryCollection(\n  $offset: Int = 0\n  $limit: Int = 100\n  $includeSongs: Boolean = false\n  $includeEpisodes: Boolean = false\n  $excludeVideos: Boolean = false\n) {\n  me {\n    # TODO: Although this field `me.library` is marked as deprecated, it is still needed because the\n    # migration of "Liked Songs" to list platform is not complete yet.\n    # @see https://spotify.atlassian.net/browse/PL-3823\n    # eslint-disable-next-line @graphql-eslint/no-deprecated\n    library {\n      tracks(offset: $offset, limit: $limit) @include(if: $includeSongs) {\n        __typename\n        totalCount\n        pagingInfo {\n          nextOffset\n          offset\n          limit\n        }\n        items {\n          item: track {\n            data {\n              __typename\n              ... on Track {\n                id\n                uri\n                name\n                saved\n                contentRating {\n                  label\n                }\n                playability {\n                  playable\n                  reason\n                }\n                duration {\n                  totalMilliseconds\n                }\n                albumOfTrack {\n                  id\n                  uri\n                  name\n                  coverArt {\n                    ...ImageParts\n                  }\n                  visualIdentity {\n                    ...MinContrastBackground\n                  }\n                }\n                artists {\n                  items {\n                    id\n                    uri\n                    profile {\n                      name\n                    }\n                  }\n                }\n                associationsV3 {\n                  audioAssociations(limit: 1, offset: 0) {\n                    items {\n                      audioThumbnailImage {\n                        data {\n                          __typename\n                          ... on ImageV2 {\n                            sources {\n                              format: imageFormat\n                              url\n                              height: maxHeight\n                              width: maxWidth\n                            }\n                          }\n                        }\n                      }\n                    }\n                    totalCount\n                  }\n                  videoAssociations(limit: 1, offset: 0) @skip(if: $excludeVideos) {\n                    items {\n                      videoThumbnailImage {\n                        data {\n                          __typename\n                          ... on ImageV2 {\n                            sources {\n                              format: imageFormat\n                              url\n                              height: maxHeight\n                              width: maxWidth\n                            }\n                          }\n                        }\n                      }\n                    }\n                    totalCount\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n      episodes(offset: $offset, limit: $limit) @include(if: $includeEpisodes) {\n        __typename\n        totalCount\n        pagingInfo {\n          nextOffset\n          offset\n          limit\n        }\n        items {\n          item: episode {\n            data {\n              __typename\n              ... on Episode {\n                uri\n                id\n                name\n                saved\n                type\n                playedState {\n                  playPositionMilliseconds\n                  state\n                }\n                description\n                htmlDescription\n                language {\n                  code\n                }\n                releaseDate {\n                  precision\n                  isoString\n                }\n                coverArt {\n                  ...ImageParts\n                }\n                visualIdentity {\n                  ...MinContrastBackground\n                }\n                playability {\n                  playable\n                  reason\n                }\n                contentRating {\n                  label\n                }\n                duration {\n                  totalMilliseconds\n                }\n                mediaTypes\n                restrictions {\n                  paywallContent\n                }\n                podcast: podcastV2 {\n                  __typename\n                  data {\n                    __typename\n                    ... on Podcast {\n                      name\n                      publisher {\n                        name\n                      }\n                      mediaHosting {\n                        externallyHosted\n                      }\n                    }\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n}\n',
